      <div class="aods-chip-group" aria-label="Active filters"><span class="aods-chip"><span class="aods-chip__label">Programs Office</span><button class="aods-chip__dismiss" type="button" aria-label="Remove filter: Programs Office"><svg class="aods-icon" data-size="sm" aria-hidden="true"><use href="#aods-close"></use></svg></button></span><span class="aods-chip"><span class="aods-chip__label">Fiscal year 2026</span><button class="aods-chip__dismiss" type="button" aria-label="Remove filter: Fiscal year 2026"><svg class="aods-icon" data-size="sm" aria-hidden="true"><use href="#aods-close"></use></svg></button></span><span class="aods-chip"><span class="aods-chip__label">Rural</span><button class="aods-chip__dismiss" type="button" aria-label="Remove filter: Rural"><svg class="aods-icon" data-size="sm" aria-hidden="true"><use href="#aods-close"></use></svg></button></span><span class="aods-chip" aria-disabled="true"><span class="aods-chip__label">Awarded</span><button class="aods-chip__dismiss" type="button" aria-label="Remove filter: Awarded"><svg class="aods-icon" data-size="sm" aria-hidden="true"><use href="#aods-close"></use></svg></button></span></div>
