  disclosure: `
    <div class="stack" style="gap:24px">
      <details class="aods-disclosure">
        <summary class="aods-disclosure__summary"><span class="aods-disclosure__index">1.1</span><span class="aods-disclosure__title">How each application review status is decided</span><span class="aods-disclosure__control" aria-hidden="true"></span></summary>
        <ul class="aods-disclosure__panel"><li class="aods-disclosure__row">Received — the application is logged and assigned a tracking number within one business day.</li><li class="aods-disclosure__row">In review — a program officer checks eligibility, completeness, and budget against the notice.</li></ul>
      </details>
      <details class="aods-disclosure" open>
        <summary class="aods-disclosure__summary"><span class="aods-disclosure__index">1.1</span><span class="aods-disclosure__title">How each application review status is decided</span><span class="aods-disclosure__control" aria-hidden="true"></span></summary>
        <ul class="aods-disclosure__panel">
          <li class="aods-disclosure__row">Received — the application is logged and assigned a tracking number within one business day.</li>
          <li class="aods-disclosure__row">In review — a program officer checks eligibility, completeness, and budget against the notice.</li>
          <li class="aods-disclosure__row">More information needed — the applicant has 30 days to supply what is missing before the file closes.</li>
          <li class="aods-disclosure__row">Recommended — the review panel has scored the application and forwarded it for final selection.</li>
          <li class="aods-disclosure__row">Awarded — funds are obligated and the grant agreement is issued to the recipient.</li>
        </ul>
      </details>
      <details class="aods-disclosure" data-density="compact" open data-divider style="margin-top:96px">
        <summary class="aods-disclosure__summary"><span class="aods-disclosure__index">1.2</span><span class="aods-disclosure__title">Compact, with dividers</span><span class="aods-disclosure__control" aria-hidden="true"></span></summary>
        <ul class="aods-disclosure__panel"><li class="aods-disclosure__row">Received — the application is logged and assigned a tracking number.</li><li class="aods-disclosure__row">In review — a program officer checks eligibility and completeness.</li><li class="aods-disclosure__row">Awarded — funds are obligated.</li></ul>
      </details>
    </div>`,

